import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String department = req.getParameter("dept");
        String sortCol = req.getParameter("sort");

        // Validate report type against allowed values
        if (reportType == null || !reportType.matches("(sales|inventory|payroll)")) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Validate date format
        if (startDate != null && !startDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid start date format");
            return;
        }
        if (endDate != null && !endDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid end date format");
            return;
        }

        // Build query - sort column is user-controlled
        String baseQuery = "SELECT id, name, amount, created_at FROM reports_" + reportType
                + " WHERE created_at BETWEEN ? AND ?";

        if (department != null && !department.isEmpty()) {
            // department is parameterized
            baseQuery += " AND department = ?";
        }

        // Sort column injection point - no validation on sortCol
        if (sortCol != null && !sortCol.isEmpty()) {
            baseQuery += " ORDER BY " + sortCol;
        } else {
            baseQuery += " ORDER BY created_at DESC";
        }

        log.info("Executing report query for type=" + reportType + " dept=" + department);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(baseQuery)) {

            stmt.setString(1, startDate != null ? startDate : "2020-01-01");
            stmt.setString(2, endDate != null ? endDate : "2099-12-31");
            if (department != null && !department.isEmpty()) {
                stmt.setString(3, department);
            }

            ResultSet rs = stmt.executeQuery();
            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                out.printf("{\"id\":%d,\"name\":\"%s\",\"amount\":\"%.2f\",\"date\":\"%s\"}",
                    rs.getInt("id"),
                    rs.getString("name").replace("\"", "\\\""),
                    rs.getDouble("amount"),
                    rs.getString("created_at"));
                first = false;
            }
            out.print("\n]");
        } catch (SQLException e) {
            log.severe("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // POST used for report export - delegates to GET logic
        doGet(req, resp);
    }
}
